import{_ as a,o as i,c as n,a4 as e}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20260709231121204.rOQzkS7l.png",l="/assets/arch-overview.CNdUb72w.png",p="/assets/dag-replenishment.BfTTRFTg.png",r="/assets/team-skill-structure.K2w1vu8W.png",h="/assets/cron-memory-loop.C2qgha-y.png",k="/assets/image-20260714194435557.BIOEOhNC.png",o="/assets/dashboard.CkeSTw0q.png",F=JSON.parse('{"title":"基于 JiuwenSwarm 的连锁餐饮采购智能编排：食材依赖自动排序 + 多门店协调 + 每日补货","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/02-餐饮供应链场景/连锁餐饮采购智能编排：食材依赖自动排序+多门店协调+每日补货.md","filePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/02-餐饮供应链场景/连锁餐饮采购智能编排：食材依赖自动排序+多门店协调+每日补货.md","lastUpdated":1785922946000,"__rawMarkdown":"# 基于 JiuwenSwarm 的连锁餐饮采购智能编排：食材依赖自动排序 + 多门店协调 + 每日补货\\n\\n> 一家连锁餐饮有几十上百家门店，每天都要补货。痛点很具体：望京店牛腱肉告急、浦东店三文鱼断档，但牛腱肉和牛肉能否互相替代、三文鱼冷链在 32℃ 高温下能不能接、四家店能不能合到同一张单……过去这些决策要么靠店长经验，要么靠一套写死在 ERP 里的补货规则。本文看 **JiuwenSwarm** 如何用蜂群协作把这些变成一个**每天自动跑、自动学**的采购 Team：食材依赖自动排序、多门店合并协调、每日补货无人值守。\\n\\n## 1. 连锁餐饮补货的三大业务难题：为什么需要 JiuwenSwarm\\n\\n![](./assets/image-20260709231121204.png)\\n\\n把\\"每天给几十家门店补货\\"这件事做好，传统方案几乎都卡在三个环节：\\n\\n| 难题               | 典型表现                                                                                    | 传统解法的痛点                                  |\\n| ------------------ | ------------------------------------------------------------------------------------------- | ----------------------------------------------- |\\n| **① 食材依赖编排** | 牛腱肉缺了，能不能用牛肉替代？三文鱼要冷链，高温天能不能接？各 SKU 之间有替代关系和先后约束 | 写死在 ERP 的补货规则里，BOM 一改就要 IT 改代码 |\\n| **② 多门店协调**   | 望京、国贸、浦东三店都要牛腱肉，能不能合成一张单凑够起订量、摊薄运费？                      | 各店各下各的单，起订量凑不齐、运费翻倍          |\\n| **③ 每日补货**     | 每天早上要有人盯着库存跑一圈，遇上周末、节假日、天气变化还得手动调整                        | 纯人工，漏一单就断货；经验也留不下来            |\\n\\nJiuwenSwarm 的解法是：**把采购变成一支会自己跑的 Agent 团队**——一个采购调度官（Leader）带几个专业 Teammate（需求预测、供应商比价、依赖校验、补货下单），每天早上 7 点自动唤醒，跑完一轮还把\\"哪家供应商爱迟到\\"这种经验沉淀下来，越跑越准。\\n\\n---\\n\\n## 2. JiuwenSwarm 核心能力一览：Swarmflow + TeamSkill + cron + 双层记忆\\n\\n**JiuwenSwarm** 是一款让多智能体真正协作起来的 Agent 系统，帮助用户通过自然语言驱动多 Agent 协作、Skill 自演进和工具调用，实现从意图到结果的端到端交付。\\n\\n落到餐饮采购场景，本文会用到这几项能力：\\n\\n- **Swarmflow（蜂群流）**：把\\"每天补货\\"这个目标自动拆成取数 → 预测 → 依赖排序 → 比价 → 下单的可执行工作流，支持并行取多店数据、条件分支（超预算走人工审批）。\\n- **Agent Team + TeamSkill**：声明式定义采购团队的四个角色，Leader 组队、分任务、收结果。\\n- **cron 定时任务**：每天 7:00 自动唤醒采购 Team，跑完结果推送到飞书，全程无需人工触发。\\n- **双层团队记忆**：每轮结束自动沉淀 `[lesson]`（供应商迟到）、`[member]`（比价 Agent 擅长生鲜）等经验，次日自动复用。\\n- **工具权限与安全防护**：`allow/ask/deny` 三级动作，超预算、改供应商主数据等敏感操作必须人工审批。\\n\\n> 一句话理解：JiuwenSwarm 不是\\"再写一个补货脚本\\"，而是把采购协作从 **\\"靠人盯 + 写死规则\\"** 变成 **\\"自动跑 + 越用越懂你的供应链\\"**。\\n\\n---\\n\\n## 3. 采购 Agent Team 构建过程：架构设计 → Swarmflow → TeamSkill 四角色 → cron 调度 + 文档解析 Skill\\n\\n### 3.1 采购团队三层架构设计\\n\\n先看全貌。下图把连锁餐饮采购映射成了三层：\\n\\n![连锁餐饮采购协作总体架构](./assets/arch-overview.png)\\n\\n- **顶层 · 蜂群协作层（采购 Team）**：一个 Leader（采购调度官）+ 四个专业 Teammate（需求预测 / 供应商比价 / 依赖校验 / 补货下单），由 Swarmflow 编排，每轮沉淀团队记忆。\\n- **中层 · 团队记忆 TEAM_MEMORY.md**：跨轮累积的供应链经验，所有成员只读。\\n- **底层 · 多门店 + 供应商数据源**：各门店的库存 ERP / POS 销售数据，以及供应商系统（通过 A2A 或报价接口接入）。\\n\\n注意图里的协作流向：Leader 把\\"今日补货\\"这个目标拆给各 Teammate；需求预测 Agent 从门店 POS 拿销量数据，比价 Agent 向供应商拉报价，依赖校验 Agent 做食材替代/冷链判断，最后由补货下单 Agent 生成采购单。整个过程由 cron 每日触发。\\n\\n---\\n\\n### 3.2 Swarmflow 工作流：食材依赖自动排序（含可执行 Python 示例）\\n\\n\\"每天补货\\"这句话，背后藏着一个有依赖关系的工作流：\\n\\n> cron 唤醒 →（四门店并行取库存/销量）→ 需求预测 → 缺口计算 + 食材依赖排序 → 供应商比价 →（超预算？人工审批）→ 生成采购单\\n\\nJiuwenSwarm 的 **Swarmflow** 做的事，就是把这套流程写成一段**可执行的 Python**，各阶段自动衔接、并行/串行/条件分支全覆盖：\\n\\n![每日补货 Swarmflow DAG](./assets/dag-replenishment.png)\\n\\n几个关键点：\\n\\n1. **并行取数（map_parallel）**：T1 阶段四家门店的库存和销量数据同时拉取，互不阻塞——这比逐店串行快得多，正是 `map_parallel` 原语的用武之地。\\n2. **依赖排序**：T3 不是简单按缺口大小排序，而是结合 BOM 替代关系（牛肉可替牛腱）和冷链约束（三文鱼高温天要全程 ≤4℃），排出真正的补货优先级。\\n3. **条件分支 + 人工审批**：T4 比价后，若某笔采购超过预算阈值（如单笔>5 万），自动进入 H1 人工审批节点——人作为\\"有状态算子\\"参与，批准才下单，驳回则 Leader 重派需求预测。\\n\\n#### 3.2.1 每日补货的工作流长什么样\\n\\nSwarmflow 的工作流是一段真实的 Python 代码，基于仓库里 [SwarmSkill 工作流模板](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/swarmskill-creator/templates/scripts/workflow.py.template) 的结构。改成餐饮补货后：\\n\\n```python\\nfrom swarmflow import agent, compact, log, map_parallel, parallel, phase\\n\\nMETA = {\\n    \\"name\\": \\"daily-replenishment\\",\\n    \\"description\\": \\"连锁餐饮每日补货：多门店取数→需求预测→依赖排序→比价→下单\\",\\n    \\"whenToUse\\": \\"每天早晨自动补货，或用户要求生成补货计划时复用\\",\\n    \\"phases\\": [\\n        {\\"title\\": \\"取数\\", \\"detail\\": \\"并行拉取各门店库存与销量\\"},\\n        {\\"title\\": \\"预测\\", \\"detail\\": \\"结合POS+天气预测各SKU需求，算缺口\\"},\\n        {\\"title\\": \\"排序\\", \\"detail\\": \\"按BOM替代关系与冷链约束排补货优先级\\"},\\n        {\\"title\\": \\"比价下单\\", \\"detail\\": \\"比价→超预算审批→生成采购单\\"},\\n    ],\\n}\\n\\nasync def run(args):\\n    # —— 阶段1 取数：四门店并行 ——\\n    phase(\\"取数\\")\\n    stores = [\\"望京\\", \\"国贸\\", \\"中关村\\", \\"浦东\\"]\\n    stock_data = await map_parallel(\\n        stores,\\n        lambda s: agent(build_prompt(\\"取门店库存销量\\", {\\"store\\": s, **args}),\\n                        label=f\\"取数-{s}\\", phase=\\"取数\\", schema=STOCK_SCHEMA),\\n    )\\n    stock_data = compact(stock_data)   # 某店接口超时不阻断其他店\\n\\n    # —— 阶段2 预测：算缺口 ——\\n    phase(\\"预测\\")\\n    forecast = await agent(\\n        build_prompt(\\"需求预测\\", {\\"stock\\": stock_data, **args}),\\n        label=\\"预测\\", phase=\\"预测\\", schema=GAP_SCHEMA,\\n    )\\n\\n    # —— 阶段3 排序：依赖/冷链校验 ——\\n    phase(\\"排序\\")\\n    ranked = await agent(\\n        build_prompt(\\"依赖排序\\", {\\"gaps\\": forecast, **args}),\\n        label=\\"排序\\", phase=\\"排序\\", schema=RANK_SCHEMA,\\n    )\\n\\n    # —— 阶段4 比价 + 条件审批 + 下单 ——\\n    phase(\\"比价下单\\")\\n    quotes = await agent(build_prompt(\\"供应商比价\\", ranked), label=\\"比价\\", phase=\\"比价下单\\", schema=QUOTE_SCHEMA)\\n    if total_amount(quotes) > args.get(\\"budget_threshold\\", 50000):\\n        log(f\\"总金额 {total_amount(quotes)} 超阈值 → 进入人工审批\\")\\n        review = await agent(build_prompt(\\"超预算审批\\", quotes), label=\\"审批\\", phase=\\"比价下单\\", schema=REVIEW_SCHEMA)\\n        if extract_json(review).get(\\"verdict\\") != \\"通过\\":\\n            return {\\"status\\": \\"degraded\\", \\"reason\\": \\"审批未通过，重派预测\\"}\\n    await agent(build_prompt(\\"生成采购单\\", quotes), label=\\"下单\\", phase=\\"比价下单\\", schema=PO_SCHEMA)\\n    return {\\"status\\": \\"complete\\", \\"date\\": args.get(\\"date\\")}\\n```\\n\\n这段代码里用到的核心原语都来自 `swarmflow` 模块：\\n\\n| 原语                                   | 在补货场景的含义                                     |\\n| -------------------------------------- | ---------------------------------------------------- |\\n| `phase(\\"...\\")`                         | 阶段标记：取数 / 预测 / 排序 / 比价下单              |\\n| `map_parallel(stores, fn)`             | 同构扇出：四家门店同时取数，适合\\"每家店都做同一件事\\" |\\n| `parallel([...])`                      | 异构并行：比如同时跑预测和供应商资质核查             |\\n| `agent(prompt, label, phase, schema)`  | 派一个 Teammate 执行，输出结构化 JSON                |\\n| `compact([...])` / `extract_json(...)` | 容错：某门店接口挂了不阻断整轮                       |\\n\\n工作流跑起来后持续吐出进度事件（`workflow_started → phase → agent_started → agent_completed → …`），前端协作台上看到的\\"T3 排序进行中\\"进度条就是这条事件流驱动的（事件派发表见 [`workflow_state.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/team/handlers/workflow_state.py)）。\\n\\n> 过去要改 ERP 补货规则、等 IT 排期才能调整的逻辑，现在改这段 Python（或改一句自然语言让 Leader 重新生成）就行，**补货策略的\\"柔性\\"第一次落到可执行代码层**。\\n\\n---\\n\\n### 3.3 TeamSkill 四角色分工：多门店协调落地（含配置文件）\\n\\n多门店协调的关键是**专业分工**：预测、比价、依赖校验、下单各是独立的专业能力，不该揉在一个大程序里。JiuwenSwarm 的 **TeamSkill（团队技能）** 标准正是为此设计——它用一个固定的五文件结构声明一支多角色团队：\\n\\n![采购 Team Skill 结构与四角色](./assets/team-skill-structure.png)\\n\\n一个 Team Skill 必须包含五个文件，缺一不可（[`/teamskills validate`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/TeamSkills.md) 会硬校验）：\\n\\n```\\nprocurement-team/\\n├── SKILL.md              # 入口：frontmatter + roles[] 角色清单\\n├── roles/                # 每个角色一个 <id>.md\\n│   ├── demand-forecaster.md\\n│   ├── supplier-scorer.md\\n│   ├── dependency-checker.md\\n│   └── order-placer.md\\n├── workflow.md           # 协作流程（含 mermaid 图 + 质量门控）\\n├── bind.md               # 并发/预算/失败兜底约束\\n└── dependencies.yaml     # 依赖的 skills + tools 声明\\n```\\n\\n`SKILL.md` 的 frontmatter 用 `kind: team-skill` 声明角色清单（基于仓库文档里的 [`medical-consultation-team`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/TeamSkills.md) 范例结构，改成采购团队）：\\n\\n```markdown\\n---\\nname: procurement-team\\nversion: 1.0.0\\ndescription: |\\n  连锁餐饮采购协同团队，调度官组织需求预测、比价、依赖校验并行评估并整合下单。\\n  Use when 需要为多门店生成每日补货采购计划。\\n  Do NOT use for 单门店单品的即时零采。\\nkind: team-skill\\nroles:\\n  - id: coordinator\\n    purpose: 汇总多门店需求、依赖排序、拆单合并、超预算人工审批\\n    skills: []\\n    tools: [send_message, create_task]\\n  - id: demand-forecaster\\n    purpose: 结合POS销量+天气/节假日预测各SKU需求\\n    skills: [advanced-daily-report]\\n    tools: []\\n  - id: supplier-scorer\\n    purpose: 比价/评分/交期，从供应商系统拉报价\\n    skills: []\\n    tools: [mcp_paid_search]\\n  - id: dependency-checker\\n    purpose: BOM替代关系校验 + 冷链约束，排补货优先级\\n    skills: []\\n    tools: []\\n  - id: order-placer\\n    purpose: 生成采购单并下发ERP/A2A\\n    skills: []\\n    tools: [write_file, mcp_exec_command]\\n---\\n```\\n\\n这里有几个**强约束**（不满足会被校验器拒）：\\n\\n- `kind` 必须是 `team-skill`（不能写成 `type`）；\\n- `roles` 至少 2 个角色，每个必须有 `id`、`purpose`（≤150 字）、`skills`、`tools` 四个字段；\\n- `name` 用 kebab-case，且要和目录名一致，通常以 `-team` 结尾。\\n\\n每个 `roles/<id>.md` 文件还有 **5 个必填段落**，这是防止角色\\"职责重叠\\"或\\"偷懒\\"的关键机制：\\n\\n1. `## Identity` — 第一行必须是**一句座右铭**（反趋同机制），比如依赖校验 Agent：`> *\\"我只信冷链温控数据，温度不达标一律拒收。\\"*`\\n2. `## Success Criteria` — 这个角色达成什么算成功；\\n3. `## Boundary` — 必须含 `**Forbidden**`（禁止越界，防止和别的角色抢活）和 `**Mandatory**`（必须做，防止偷懒）；\\n4. `## Output Schema` — 结构化输出格式；\\n5. `## Inline Persona for Teammate` — 一段可直接注入的完整 prompt。\\n\\n> 这个设计的精妙之处在于：**座右铭 + Forbidden/Mandatory** 让每个角色都有自己的\\"性格\\"和边界，不会所有 Agent 都往一个方向收敛。比如比价 Agent 被 Forbidden 碰下单决策，下单 Agent 被 Forbidden 改报价——各司其职，互不越界。\\n\\n#### 3.3.1 采购团队的真实配置文件\\n\\n\\"组建团队\\"除了 Team Skill，还有运行时的声明式配置。下面是从仓库 [`config.team.distributed.leader.yaml`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/config.team.distributed.leader.yaml) 摘出的核心结构，改成采购场景：\\n\\n```yaml\\nmodes:\\n  team:\\n    procurement_team:\\n      team_name: procurement_team\\n      lifecycle: persistent # 持久团队：记忆跨轮累积（每日补货的关键）\\n      enable_swarmflow: true # 跑前面的补货工作流\\n      leader:\\n        member_name: team_leader\\n        display_name: 采购调度官\\n        persona: \\"资深供应链调度专家，擅长多门店需求合并、食材依赖编排与异常协调\\"\\n      memory:\\n        enabled: true\\n        auto_extract: true # 每轮结束自动提取团队记忆\\n        shared_memory: true # 写入 TEAM_MEMORY.md\\n        member_memory_prompt_mode: \\"proactive\\"\\n```\\n\\n- `lifecycle: persistent` 是每日补货能\\"越跑越准\\"的前提——团队记忆跨轮累积；临时团队（`temporary`）跑完即散，不留经验。\\n- `enable_swarmflow: true` 让这个团队跑前面那段可执行工作流。\\n\\n真正让团队跑起来的入口是 SDK 流式执行器（[`team_helpers.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/server/runtime/agent_adapter/team_helpers.py)），Leader 收到目标后用 `build_team` / `create_task` / `spawn_teammate` / `send_message` 这套团队工具（系统提示约束，见 [`code_rails.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/swarm/providers/code_rails.py)）去分工推进。\\n\\n---\\n\\n### 3.4 cron 定时唤醒 + 团队记忆沉淀：每日补货无人值守\\n\\n前面两个能力解决了\\"怎么补\\"和\\"谁来补\\"，但还差一个\\"谁来触发\\"。餐饮补货是高频重复的事，不该每天靠人喊一嗓子。JiuwenSwarm 的 **cron 定时任务** + **团队记忆** 把它变成了真正的无人值守：\\n\\n![cron 定时 + 团队记忆闭环](./assets/cron-memory-loop.png)\\n\\n#### 3.4.1 用 cron 每天 7 点自动唤醒采购团队\\n\\n仓库的 cron 工具（[`cron_tools.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/common/tools/cron/cron_tools.py)，提供 `cron_create_job` 等 8 个工具）支持以 `mode=team` 定时拉起一个团队。最自然的方式是直接对话：\\n\\n```\\n/cron add name=每日补货计划 cron_expr=\\"0 7 * * 1-5\\" \\\\\\n  description=\\"读取昨日各门店库存与销售，对比安全库存水位，生成今日补货建议清单（含供应商、SKU、数量、预计到货时间）\\" \\\\\\n  mode=team targets=feishu\\n```\\n\\n![](assets/image-20260714194435557.png)\\n\\n对应到代码里，`cron_create_job` 的真实参数（节选）：\\n\\n```python\\ninput_params = {\\n    \\"name\\": \\"每日补货计划\\",\\n    \\"cron_expr\\": \\"0 7 * * 1-5\\",        # 工作日早7点\\n    \\"timezone\\": \\"Asia/Shanghai\\",\\n    \\"mode\\": \\"team\\",                    # 以团队模式运行\\n    \\"targets\\": \\"feishu\\",               # 结果推送到飞书\\n    \\"wake_offset_seconds\\": 30,         # 提前30秒唤醒Agent\\n    \\"enabled\\": True,\\n}\\n```\\n\\n到点后系统在独立 session（`cron_{时间戳}_{job_id}`）里跑一轮采购 Team，结果（采购单 + 异常预警）推送到飞书群。`targets` 还支持 `web`/`dingtalk`/`wecom`/`wechat` 等渠道。\\n\\n#### 3.4.2 每跑一轮，沉淀一次供应链经验\\n\\n更关键的是右半边的**记忆闭环**。在 `lifecycle: persistent` 的团队里，**Leader 会在每轮结束时派一个提取 Agent**，读本轮的任务记录和团队消息，蒸馏出值得保留的经验，写入 `TEAM_MEMORY.md`（[`memory_tools.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/common/tools/memory_tools.py) + 团队记忆机制）。记忆分四类标签：\\n\\n| 标签         | 含义                             | 采购场景举例                             |\\n| ------------ | -------------------------------- | ---------------------------------------- |\\n| `[lesson]`   | 经验教训：什么有效、什么导致返工 | \\"永辉冷链冻品常迟到 2 天，需备安全库存\\"  |\\n| `[decision]` | 团队决策：为何选 A 不选 B        | \\"单笔超 5 万走人工审批\\"                  |\\n| `[member]`   | 成员特长：谁擅长什么             | \\"比价 Agent 擅长生鲜议价\\"                |\\n| `[context]`  | 业务上下文：约束、截止日         | \\"本周三中粮食用油走周合同价，不重新议价\\" |\\n\\n这些条目**跨轮累积、所有成员只读**，文件自动保持在 200 行以内（提取 Agent 会合并/更新/淘汰旧条目）。次日 7 点再跑时，比价 Agent 就能读到\\"永辉爱迟到\\"的教训，自动给更稳的供应商加权。\\n\\n> 这就是\\"越跑越准\\"的本质：不是模型变聪明了，而是**供应链经验以结构化记忆的形式持续沉淀、自动复用**。\\n\\n---\\n\\n### 3.5 文档解析 Skill：报价单/发票自动结构化录入\\n\\n采购场景还有大量\\"非结构化输入\\"：供应商发来的报价单 PDF、发票图片、进货单 Excel。JiuwenSwarm 仓库里内置的 [`financial-document-parser`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/financial-document-parser/SKILL.md) 技能正好能干这事——它用 `pdfplumber` 解析文本 PDF、用 `pytesseract` + `pdf2image` 对扫描件做 OCR 兜底，输出结构化的 Markdown/JSON/CSV：\\n\\n```\\n| 类型 | 格式 | 提取内容 |\\n| 发票 | PDF | 发票号、日期、供应商、明细、税额、总额 |\\n| 收据 | PDF/图片 | 商户、日期、商品、金额 |\\n| 银行对账单 | PDF/CSV | 交易明细、余额、费用 |\\n```\\n\\n在采购 Team 里，可以让供应商比价 Agent 调这个技能解析供应商报价单（`allowed_tools: [bash]` 调 `financial_parser.py`），把\\"牛腱肉 ¥38/kg、起订 200kg\\"这种信息从 PDF 里抠出来喂给比价流程。它还支持批量处理：\\n\\n```bash\\nfor f in 报价单/*.pdf; do\\n  python financial_parser.py \\"$f\\" --format json\\ndone\\n```\\n\\n这样新供应商发来的报价单不用人工录入，技能自动解析进结构化数据。\\n\\n---\\n\\n## 4. 补货协作台效果展示：Swarmflow 进度 + Team 状态 + 校验日志一张屏\\n\\n![每日补货协作台](./assets/dashboard.png)\\n\\n协作台分三栏，对应本文的三大主题：\\n\\n- **左栏 · 多门店库存水位 + 需求预测**：四家门店的安全库存水位条（望京店缺口 8 SKU 标红），下方是 T2 需求预测结果（牛腱肉因降温+周末预测+32%、三文鱼因高温预警-12%）。\\n- **中栏 · 补货金额走势 + Swarmflow 进度**：近 7 天实际补货 vs 预算上限曲线（今日触及预警线），下方是工作流实时进度 `T1取数✓ → T2预测✓ → T3排序(进行中)`。\\n- **右栏 · 今日采购单 + 依赖/冷链校验**：按依赖排序的采购单 TOP（三文鱼 ¥5.1 万 标 ⚠ 触发超预算审批 H1），下方是 T3 的 BOM/冷链校验日志（牛肉可替牛腱 ✓、三文鱼冷链高温告警 ⚠）。\\n\\n> 这张台背后没有\\"每天手动跑一遍\\"的操作——所有取数、预测、排序、比价、审批触发，都由 cron 唤醒的采购 Team 自动完成，本轮经验自动写进团队记忆。\\n\\n---\\n\\n## 5. 四阶段落地路线图与总结\\n\\n如果你也想在自家连锁餐饮上落地，建议按这个节奏来：\\n\\n1. **先单店跑通一轮补货**：1 个 Leader + 2~3 个 Teammate（需求预测 + 比价 + 下单），手动触发验证 Swarmflow DAG 和依赖排序逻辑。\\n2. **扩到多门店 + 上 cron**：用 `map_parallel` 并行取数，配 `cron_create_job` 每日 7 点自动唤醒，结果推飞书。\\n3. **开启团队记忆**：团队设 `lifecycle: persistent`，让供应商迟到、替代关系等经验自动沉淀，跑一周后对比补货准确率。\\n4. **配好安全策略**：超预算、改供应商主数据、首次合作下单等用 `ask`/`deny` 卡住人工审批（权限配置见 [`工具权限与安全防护`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/工具权限与安全防护.md)）。\\n\\n### 5.1 三句话总结\\n\\n- **食材依赖自动排序**：Swarmflow 把补货流程变成可执行 DAG，BOM 替代关系 + 冷链约束 + 优先级全自动判断，不再写死在 ERP 里。\\n- **多门店协调**：采购 Team Skill 声明式定义四角色，座右铭+Forbidden/Mandatory 机制保证各司其职，四店需求自动合并凑起订量。\\n- **每日补货无人值守**：cron 每天 7 点唤醒 + 团队记忆每轮沉淀，供应链经验越跑越准，真正实现\\"自动跑、自动学\\"。\\n\\n随着 Agent 协同在更多供应链场景落地，**\\"经验驱动 + 自动编排\\"的采购模式将成为连锁餐饮控本提效的关键**——而 JiuwenSwarm 让这条路触手可及。\\n\\n---\\n\\n## 6. JiuwenSwarm 文档与资源索引\\n\\n1. JiuwenSwarm 官网：<https://openjiuwen.com>\\n2. JiuwenSwarm 仓库（GitCode）：<https://gitcode.com/openJiuwen/jiuwenswarm>\\n3. 官方文档：\\n   - [TeamSkill 团队技能指南](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/TeamSkills.md)\\n   - [Agent Team 使用指南](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/AgentTeam.md)\\n   - [定时任务 cron](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/定时任务.md)\\n   - [记忆系统](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/记忆.md)\\n   - [工具权限与安全防护](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/工具权限与安全防护.md)\\n4. 相关技能：[`advanced-daily-report`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/advanced-daily-report/SKILL.md)、[`financial-document-parser`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/financial-document-parser/SKILL.md)、[`swarmskill-creator`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/swarmskill-creator/SKILL.md)\\n"}'),d={name:"AI人工智能/jiuwenswarm-垂直行业技术文章/02-餐饮供应链场景/连锁餐饮采购智能编排：食材依赖自动排序+多门店协调+每日补货.md"};function E(c,s,g,m,u,y){return i(),n("div",null,[...s[0]||(s[0]=[e("",92)])])}const w=a(d,[["render",E]]);export{F as __pageData,w as default};
